function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // two stick figures
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // figure 1
  ctx.beginPath();
  ctx.arc(W/4 + Math.sin(t)*20, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + Math.sin(t)*20, H/2 + 20);
  ctx.lineTo(W/4 + Math.sin(t)*20, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + Math.sin(t)*20, H/2 + 50);
  ctx.lineTo(W/4 + Math.sin(t)*20 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + Math.sin(t)*20, H/2 + 50);
  ctx.lineTo(W/4 + Math.sin(t)*20 + 20, H/2 + 70);
  ctx.stroke();

  // figure 2
  ctx.beginPath();
  ctx.arc(W - W/4 + Math.cos(t)*20, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + Math.cos(t)*20, H/2 + 20);
  ctx.lineTo(W - W/4 + Math.cos(t)*20, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + Math.cos(t)*20, H/2 + 50);
  ctx.lineTo(W - W/4 + Math.cos(t)*20 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + Math.cos(t)*20, H/2 + 50);
  ctx.lineTo(W - W/4 + Math.cos(t)*20 + 20, H/2 + 70);
  ctx.stroke();

  // moving towards each other
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 120);
  ctx.lineTo(W/2 + Math.cos(t)*50, H/2 + 120);
  ctx.stroke();

  ctx.restore();
}
